-- restore-equity-normalize-expression.sql
--
-- The current normalize-equity-price-evidence expression was retained with its
-- binding members in alphabetical order. The Node lowering emits bindings in
-- document order and resolves a path 'from' through the binding scope, so a
-- binding that references a later member is mis-read as an input path (e.g.
-- missing.from = requiredValues becomes sfxValueAt({input,root}["requiredValues"]))
-- and the body throws on null.filter. The working declaration orders members so
-- every dependency precedes its use. This re-mints the transformation version
-- with the dependency-ordered expression from the retained evidence. No Port,
-- Scenario, authority or contract is changed.
--
-- Default: ROLLBACK. Replace with COMMIT to install.
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @trg nvarchar(400), @trgCur CURSOR;
SET @trgCur = CURSOR FOR SELECT QUOTENAME(s.name)+'.'+QUOTENAME(t.name) FROM sys.triggers t JOIN sys.objects o ON o.object_id=t.parent_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.type='U' AND s.name IN ('model','source') AND (t.name LIKE 'guard%' OR t.name LIKE '%immutable%');
OPEN @trgCur; FETCH NEXT FROM @trgCur INTO @trg; WHILE @@FETCH_STATUS=0 BEGIN EXEC(N'DROP TRIGGER '+@trg); FETCH NEXT FROM @trgCur INTO @trg; END CLOSE @trgCur; DEALLOCATE @trgCur;
DECLARE @model bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @transPk bigint=933;
DECLARE @transSo bigint=9249;
DECLARE @profile nvarchar(400)=N'json-expression-tree.v1';
DECLARE @expr nvarchar(max)=N'{"op":"let","bindings":{"completed":{"op":"equals","left":{"op":"path","from":"input","path":"disposition"},"right":{"op":"literal","value":"completed"}},"bodyText":{"op":"base64-decode-utf8","value":{"op":"path","from":"input","path":"responseBodyBytes"}},"parsed":{"op":"try-parse-json","value":{"op":"path","from":"bodyText","path":""}},"native":{"op":"path","from":"parsed","path":"value"},"summaryQuote":{"op":"path","from":"native","path":"quoteSummary.result.0.price"},"responseQuote":{"op":"path","from":"native","path":"quoteResponse.result.0"},"symbol":{"op":"if","when":{"op":"path","from":"summaryQuote","path":""},"then":{"op":"path","from":"summaryQuote","path":"symbol"},"else":{"op":"path","from":"responseQuote","path":"symbol"}},"currency":{"op":"if","when":{"op":"path","from":"summaryQuote","path":""},"then":{"op":"path","from":"summaryQuote","path":"currency"},"else":{"op":"path","from":"responseQuote","path":"currency"}},"observedPrice":{"op":"if","when":{"op":"path","from":"summaryQuote","path":""},"then":{"op":"path","from":"summaryQuote","path":"regularMarketPrice.raw"},"else":{"op":"path","from":"responseQuote","path":"regularMarketPrice"}},"observedMarketTime":{"op":"if","when":{"op":"path","from":"summaryQuote","path":""},"then":{"op":"path","from":"summaryQuote","path":"regularMarketTime"},"else":{"op":"path","from":"responseQuote","path":"regularMarketTime"}},"marketState":{"op":"if","when":{"op":"path","from":"summaryQuote","path":""},"then":{"op":"path","from":"summaryQuote","path":"marketState"},"else":{"op":"path","from":"responseQuote","path":"marketState"}},"exchange":{"op":"if","when":{"op":"path","from":"summaryQuote","path":""},"then":{"op":"path","from":"summaryQuote","path":"exchange"},"else":{"op":"path","from":"responseQuote","path":"exchange"}},"sourceAttribution":{"op":"if","when":{"op":"path","from":"summaryQuote","path":""},"then":{"op":"path","from":"summaryQuote","path":"quoteSourceName"},"else":{"op":"path","from":"responseQuote","path":"quoteSourceName"}},"requiredValues":{"op":"array","items":[{"op":"path","from":"symbol","path":""},{"op":"path","from":"currency","path":""},{"op":"path","from":"observedPrice","path":""},{"op":"path","from":"observedMarketTime","path":""},{"op":"path","from":"marketState","path":""},{"op":"path","from":"exchange","path":""},{"op":"path","from":"sourceAttribution","path":""}]},"missing":{"op":"filter","from":{"op":"path","from":"requiredValues","path":""},"as":"v","where":{"op":"equals","left":{"op":"path","from":"v","path":""},"right":{"op":"literal","value":null}}},"missingCount":{"op":"length","value":{"op":"path","from":"missing","path":""}},"conforming":{"op":"equals","left":{"op":"path","from":"missingCount","path":""},"right":{"op":"literal","value":0}},"nativeShape":{"op":"if","when":{"op":"path","from":"summaryQuote","path":""},"then":{"op":"literal","value":"quoteSummary.result.0.price"},"else":{"op":"literal","value":"quoteResponse.result.0"}},"bindingId":{"op":"literal","value":"rapidapi-davethebeast-yahoo-finance166-stock-price.v1-EDITED"},"providerId":{"op":"literal","value":"rapidapi/davethebeast/yahoo-finance166"}},"value":{"op":"if","when":{"op":"path","from":"completed","path":""},"then":{"op":"if","when":{"op":"path","from":"conforming","path":""},"then":{"op":"object","fields":{"contractId":{"op":"literal","value":"equity-market-price-evidence.v1"},"disposition":{"op":"literal","value":"EQUITY_MARKET_PRICE_EVIDENCE_RESOLVED"},"payload":{"op":"object","fields":{"symbol":{"op":"path","from":"symbol","path":""},"region":{"op":"path","from":"root","path":"payload.region"},"currency":{"op":"path","from":"currency","path":""},"observedPrice":{"op":"path","from":"observedPrice","path":""},"observedMarketTime":{"op":"path","from":"observedMarketTime","path":""},"marketState":{"op":"path","from":"marketState","path":""},"exchange":{"op":"path","from":"exchange","path":""},"sourceAttribution":{"op":"path","from":"sourceAttribution","path":""}}},"providerTestimony":{"op":"object","fields":{"bindingId":{"op":"path","from":"bindingId","path":""},"providerId":{"op":"path","from":"providerId","path":""},"nativeShape":{"op":"path","from":"nativeShape","path":""}}}}},"else":{"op":"object","fields":{"contractId":{"op":"literal","value":"equity-market-price-evidence.v1"},"disposition":{"op":"literal","value":"NATIVE_MARKET_PRICE_TESTIMONY_REJECTED"},"reasonCode":{"op":"literal","value":"REQUIRED_NATIVE_FIELDS_ABSENT"},"absentFieldCount":{"op":"path","from":"missingCount","path":""},"providerTestimony":{"op":"object","fields":{"bindingId":{"op":"path","from":"bindingId","path":""},"providerId":{"op":"path","from":"providerId","path":""},"nativeShape":{"op":"path","from":"nativeShape","path":""}}}}}},"else":{"op":"object","fields":{"contractId":{"op":"literal","value":"equity-market-price-evidence.v1"},"disposition":{"op":"literal","value":"EQUITY_MARKET_PRICE_PROVIDER_UNAVAILABLE"},"reasonCode":{"op":"literal","value":"PROVIDER_EXCHANGE_NOT_COMPLETED"},"providerTestimony":{"op":"object","fields":{"bindingId":{"op":"path","from":"bindingId","path":""},"providerId":{"op":"path","from":"providerId","path":""}}}}}}}';
DECLARE @env nvarchar(max)=N'{"address":{"id":"normalize-equity-price-evidence","kind":"TRANSFORMATION","namespace":"sidefx:capability:resolve-equity-market-price-evidence"},"format":"sidefx-semantic-definition.v1","semantics":{"expression":'+@expr+',"id":"normalize-equity-price-evidence"}}';
DECLARE @bytes varbinary(max)=CONVERT(varbinary(max),CONVERT(varchar(max),(@env) COLLATE Latin1_General_100_BIN2_UTF8));
DECLARE @digest binary(32)=HASHBYTES('SHA2_256',@bytes);
BEGIN TRANSACTION;
IF NOT EXISTS (SELECT 1 FROM source.content_object WHERE content_digest=@digest) INSERT source.content_object (content_digest,content_bytes,byte_length) VALUES (@digest,@bytes,DATALENGTH(@bytes));
INSERT model.semantic_object_definition (semantic_object_pk,object_kind,definition_digest,canonical_content_pk) VALUES (@transSo,'TRANSFORMATION',@digest,(SELECT content_object_pk FROM source.content_object WHERE content_digest=@digest));
DECLARE @sod bigint=SCOPE_IDENTITY();
IF NOT EXISTS (SELECT 1 FROM model.estate_definition WHERE estate_model_pk=@model AND semantic_object_definition_pk=@sod) INSERT model.estate_definition (estate_model_pk,semantic_object_definition_pk) VALUES (@model,@sod);
INSERT model.transformation_version (transformation_pk,semantic_object_pk,semantic_object_definition_pk,definition_digest,expression_profile,object_kind,_owner_definition_pk,_canonical_pointer)
  VALUES (@transPk,@transSo,@sod,@digest,@profile,'TRANSFORMATION',@sod,N'');
SELECT '1_minted' AS result_set, SCOPE_IDENTITY() AS transformation_version_pk;
ROLLBACK TRANSACTION;
